package com.focusflow.api.service; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.entity.*; import com.focusflow.api.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*; @Service public class TaskService {final TaskRepository tasks;final UserRepository users;public TaskService(TaskRepository t,UserRepository u){tasks=t;users=u;} TaskResponse map(Task t){return new TaskResponse(t.id,t.title,t.description,t.status,t.priority,t.category,t.dueDate,t.dueTime,t.reminder,t.completedAt,t.createdAt,t.updatedAt);} Task owned(String id,String uid){return tasks.findByIdAndUserId(id,uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Task not found"));} public List<TaskResponse> all(String u){return tasks.findByUserIdOrderByDueDateAscDueTimeAsc(u).stream().map(this::map).toList();} public TaskResponse one(String id,String u){return map(owned(id,u));} public TaskResponse create(TaskRequest r,String uid){var t=new Task();t.user=users.getReferenceById(uid);apply(t,r);return map(tasks.save(t));} public TaskResponse update(String id,TaskRequest r,String u){var t=owned(id,u);apply(t,r);return map(tasks.save(t));} public TaskResponse complete(String id,String u){var t=owned(id,u);t.status=Task.Status.COMPLETED;t.completedAt=Instant.now();return map(tasks.save(t));} public void delete(String id,String u){tasks.delete(owned(id,u));} public List<TaskResponse> today(String u){return tasks.findByUserIdAndDueDate(u,LocalDate.now()).stream().map(this::map).toList();} public List<TaskResponse> upcoming(String u){return tasks.findByUserIdAndDueDateAfter(u,LocalDate.now()).stream().map(this::map).toList();} public List<TaskResponse> overdue(String u){return tasks.findByUserIdAndDueDateBeforeAndStatusNot(u,LocalDate.now(),Task.Status.COMPLETED).stream().map(this::map).toList();} private void apply(Task t,TaskRequest r){t.title=r.title();t.description=r.description();t.status=r.status()==null?Task.Status.TODO:r.status();t.priority=r.priority()==null?Task.Priority.MEDIUM:r.priority();t.category=r.category();t.dueDate=r.dueDate();t.dueTime=r.dueTime();t.reminder=r.reminder();t.completedAt=t.status==Task.Status.COMPLETED?(t.completedAt==null?Instant.now():t.completedAt):null;} }
